fams={
 'c*t^a*exp(-kP)': lambda q: q[0]*tv**q[1]*np.exp(-q[2]*Pv),
 'c*P^a*exp(-kt)': lambda q: q[0]*Pv**q[1]*np.exp(-q[2]*tv),
 'c*P*t^a*exp(-kt)': lambda q: q[0]*Pv*tv**q[1]*np.exp(-q[2]*tv),
