 'c*P^a*cos(kt)': lambda q: q[0]*Pv**q[1]*np.cos(q[2]*tv),
 'c*P^a*sin(kP)': lambda q: q[0]*Pv**q[1]*np.sin(q[2]*Pv),
 'c*sqrtP*t*exp(-kt)': lambda q: q[0]*np.sqrt(Pv)*tv*np.exp(-q[1]*tv),
